using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Shapes;using System.Text.Json;using FacialPresets;
namespace DanceStudio;
public sealed class StrengthCurveView:Canvas {
 readonly ToolTip liveTip=new(){StaysOpen=true,Placement=System.Windows.Controls.Primitives.PlacementMode.MousePoint};
 readonly bool large;readonly Action begin,commit,cancel;readonly Action? choose;bool dragging;double originalGain;bool amplification;List<StrengthPoint>? original;Guid? selection;public FacialSegment Segment{get;}public event Action? PointSelected;
 public bool AllowAmplification {get=>amplification;set{if(amplification==value)return;CancelDrag();amplification=value;Render();}}
 public double Maximum=>AllowAmplification?4:1;
 // Keep already-authored amplified data visible when editing is locked again.
 public double AxisMaximum=>AllowAmplification||Segment.Gain>1?4:1;
 public StrengthPoint? SelectedPoint=>Segment.StrengthCurve?.FirstOrDefault(p=>p.Id==selection);
 double Left=>large?44:2;double Top=>large?23:2;double PlotWidth=>Math.Max(1,ActualWidth-Left-(large?14:2));double PlotHeight=>Math.Max(1,ActualHeight-Top-(large?22:2));
 double X(double time)=>Left+(time-Segment.EnvelopeOffset)/(Segment.End-Segment.Start)*PlotWidth;
 double Y(double value)=>Top+(1-value/AxisMaximum)*PlotHeight;
 public StrengthCurveView(FacialSegment segment,bool enlarged,Action onBegin,Action onCommit,Action onCancel,Action? onChoose=null){Segment=segment;large=enlarged;begin=onBegin;commit=onCommit;cancel=onCancel;choose=onChoose;Focusable=true;Background=Brushes.Transparent;ClipToBounds=true;MinHeight=large?130:0;SizeChanged+=(_,_)=>Render();
  PreviewMouseLeftButtonDown+=(_,e)=>{if((Keyboard.Modifiers&ModifierKeys.Alt)!=0)return;var at=e.GetPosition(this);var point=Segment.StrengthCurve?.Where(p=>Math.Abs(X(p.Time)-at.X)<7&&Math.Abs(Y(p.Value*Segment.Gain)-at.Y)<8).FirstOrDefault();bool add=(Keyboard.Modifiers&ModifierKeys.Control)!=0;if(point==null&&!add){if(large){Focus();selection=null;PointSelected?.Invoke();}return;}e.Handled=true;choose?.Invoke();Focus();if(point!=null&&point.Value*Segment.Gain>Maximum){selection=point.Id;Render();PointSelected?.Invoke();return;}begin();original=Clone(Segment.StrengthCurve);originalGain=Segment.Gain;if(add&&point==null)point=InsertPoint(AtTime(at.X),AtValue(at.Y));selection=point!.Id;dragging=true;CaptureMouse();Render();PointSelected?.Invoke();};
  MouseMove+=(_,e)=>{if(!dragging)return;var p=e.GetPosition(this);MoveSelected(AtTime(p.X),AtValue(p.Y));liveTip.PlacementTarget=this;liveTip.Content=$"{SelectedPoint?.Time:0.000} s · {SelectedPoint?.Value*Segment.Gain*100:0.0}%";liveTip.IsOpen=true;e.Handled=true;};
  MouseLeftButtonUp+=(_,e)=>{if(!dragging)return;dragging=false;liveTip.IsOpen=false;ReleaseMouseCapture();commit();e.Handled=true;};
  LostMouseCapture+=(_,_)=>{if(dragging)CancelDrag();};
  PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape&&dragging){CancelDrag();e.Handled=true;}else if(e.Key==Key.Delete&&SelectedPoint!=null){DeleteSelected();e.Handled=true;}};
  MouseRightButtonUp+=(_,e)=>{var p=e.GetPosition(this);selection=Segment.StrengthCurve?.FirstOrDefault(k=>Math.Abs(X(k.Time)-p.X)<8&&Math.Abs(Y(k.Value*Segment.Gain)-p.Y)<8)?.Id;if(selection==null)return;choose?.Invoke();PointSelected?.Invoke();var menu=new ContextMenu();var remove=new MenuItem{Header=UiText.T("curveDelete")};remove.Click+=(_,_)=>DeleteSelected();menu.Items.Add(remove);ContextMenu=menu;menu.IsOpen=true;e.Handled=true;};Render();
 }
 static List<StrengthPoint>? Clone(List<StrengthPoint>? points)=>points==null?null:JsonSerializer.Deserialize<List<StrengthPoint>>(JsonSerializer.Serialize(points));
 double AtTime(double x)=>Math.Clamp(Segment.EnvelopeOffset+(x-Left)/PlotWidth*(Segment.End-Segment.Start),Segment.EnvelopeOffset,Segment.EnvelopeOffset+Segment.End-Segment.Start);
 double AtValue(double y)=>Math.Clamp((1-(y-Top)/PlotHeight)*AxisMaximum,0,Maximum);
 void SetIntensity(StrengthPoint point,double value){double oldGain=Segment.Gain;if(value>oldGain){Segment.Gain=value;foreach(var p in Segment.StrengthCurve!)p.Value*=oldGain/value;}point.Value=Segment.Gain>0?value/Segment.Gain:0;}
 public StrengthPoint InsertPoint(double time,double value){if(!double.IsFinite(time)||!double.IsFinite(value)||time<0||time>StrengthCurves.Duration(Segment)||value<0||value>Maximum)throw new System.IO.InvalidDataException(UiText.T("curveInvalid"));StrengthCurves.ConvertFade(Segment);var point=Segment.StrengthCurve!.FirstOrDefault(p=>Math.Abs(p.Time-time)<1e-6);if(point==null){point=new(){Time=time,Value=0};Segment.StrengthCurve!.Add(point);Segment.StrengthCurve.Sort((a,b)=>a.Time.CompareTo(b.Time));}SetIntensity(point,value);selection=point.Id;Render();PointSelected?.Invoke();return point;}
 public void SelectPoint(Guid id){selection=id;Render();PointSelected?.Invoke();}
 public void MoveSelected(double time,double value){if(!double.IsFinite(time)||!double.IsFinite(value))throw new System.IO.InvalidDataException(UiText.T("curveInvalid"));if(SelectedPoint is not {} point)return;var sorted=Segment.StrengthCurve!.OrderBy(p=>p.Time).ToArray();int index=Array.IndexOf(sorted,point);double min=index>0?Math.BitIncrement(sorted[index-1].Time):0,max=index+1<sorted.Length?Math.BitDecrement(sorted[index+1].Time):StrengthCurves.Duration(Segment);point.Time=Math.Clamp(time,min,Math.Max(min,max));SetIntensity(point,Math.Clamp(value,0,Maximum));Render();PointSelected?.Invoke();}
 public void EditSelected(double time,double value,string interpolation){if(!double.IsFinite(time)||!double.IsFinite(value)||time<0||time>StrengthCurves.Duration(Segment)||value<0||value>Maximum||interpolation is not ("Linear" or "Hold"))throw new System.IO.InvalidDataException(UiText.T("curveInvalid"));if(SelectedPoint==null)return;begin();MoveSelected(time,value);SelectedPoint.Interpolation=interpolation;PointSelected?.Invoke();StrengthCurves.Validate(Segment);commit();}
 public void DeleteSelected(){if(SelectedPoint is not {} point)return;begin();Segment.StrengthCurve!.Remove(point);if(Segment.StrengthCurve.Count==0)Segment.StrengthCurve.Add(new(){Time=0,Value=1});selection=null;commit();Render();PointSelected?.Invoke();}
 public void CancelDrag(){if(!dragging)return;dragging=false;liveTip.IsOpen=false;Segment.StrengthCurve=Clone(original);Segment.Gain=originalGain;ReleaseMouseCapture();cancel();Render();PointSelected?.Invoke();}
 public void Render(){Children.Clear();if(ActualWidth<=0)return;void Line(double x,double y,double x2,double y2,Brush color,double thickness=1)=>Children.Add(new Line{X1=x,Y1=y,X2=x2,Y2=y2,Stroke=color,StrokeThickness=thickness,IsHitTestVisible=false});
  if(large){foreach(double v in AxisMaximum>1?new[]{0.0,1,2,3,4}:new[]{0.0,.5,1}){Line(Left,Y(v),Left+PlotWidth,Y(v),StudioTheme.Line);var text=new TextBlock{Text=(v*100).ToString("0")+"%",Foreground=StudioTheme.Muted,FontSize=10,IsHitTestVisible=false};SetLeft(text,0);SetTop(text,Y(v)-7);Children.Add(text);}for(int i=0;i<=4;i++){double t=Segment.EnvelopeOffset+(Segment.End-Segment.Start)*i/4;var text=new TextBlock{Text=t.ToString("0.###")+"s",Foreground=StudioTheme.Muted,FontSize=10,IsHitTestVisible=false};SetLeft(text,X(t)-10);SetTop(text,Top+PlotHeight+4);Children.Add(text);}}
  // Include authored breakpoints: Hold edges remain vertical, not resampled ramps.
  double from=Segment.EnvelopeOffset,to=from+Segment.End-Segment.Start;var points=(Segment.StrengthCurve??[]).Select(p=>p.Time).Concat(new[]{from,to}).Where(t=>t>=from&&t<=to).Distinct().Order().ToArray();if(Segment.StrengthCurve==null)points=points.Concat(new[]{Segment.FadeIn,StrengthCurves.Duration(Segment)-Segment.FadeOut}.Where(t=>t>from&&t<to)).Order().ToArray();for(int i=0;i+1<points.Length;i++){double a=points[i],b=points[i+1],end=StrengthCurves.Envelope(Segment,b);var previous=Segment.StrengthCurve?.Where(p=>p.Time<=a).OrderBy(p=>p.Time).LastOrDefault();double before=previous?.Interpolation=="Hold"?StrengthCurves.Envelope(Segment,a):end;Line(X(a),Y(StrengthCurves.Envelope(Segment,a)*Segment.Gain),X(b),Y(before*Segment.Gain),StudioTheme.Accent,large?2:1.5);if(before!=end)Line(X(b),Y(before*Segment.Gain),X(b),Y(end*Segment.Gain),StudioTheme.Accent,2);}
  foreach(var p in Segment.StrengthCurve??[]){if(p.Time<from||p.Time>to)continue;double size=large?9:6;var dot=new Ellipse{Width=size,Height=size,Fill=p.Id==selection?Brushes.White:StudioTheme.Accent,Stroke=StudioTheme.Background,StrokeThickness=1,IsHitTestVisible=false};SetLeft(dot,X(p.Time)-size/2);SetTop(dot,Y(p.Value*Segment.Gain)-size/2);Children.Add(dot);}
 }
}
